const translations={'NextPosition':'下一站','YOUR NEXT CHAPTER':'你的下一站','Less scattered.':'少一点忙乱，','More prepared.':'多一点从容。','A calm workspace for PhD, doctoral researcher and RA applications.':'把感兴趣的岗位、材料与申请进度放在一起。','◫   Opportunities':'◫   全部申请','◷   Due in 14 days':'◷   两周内截止','Browser-local workspace':'保存在当前浏览器','No account. No sync.':'无需账号，暂不支持同步。','No automatic applications.':'由你决定何时申请。','Privacy & limitations':'数据与隐私','APPLICATION WORKSPACE':'我的申请','Your next chapter, organized.':'让下一站，有条不紊。','Track the opportunity. Prepare the materials. Keep the decision yours.':'收藏机会，准备材料，按自己的节奏向前。','+ Add opportunity':'＋ 添加申请','Active opportunities':'正在进行','Due within 14 days · UTC dates':'两周内截止','Materials still in progress':'待准备材料','Interviews & offers':'面试与录取','Opportunity board':'我的申请','Try fictional examples':'查看示例','Export backup':'导出备份','Export CSV':'导出表格','Import backup':'导入备份','Search':'搜索','Search role, institution or notes…':'搜索岗位、机构或笔记…','Stage':'进度','Country':'国家','All stages':'全部进度','All countries':'全部国家','OPPORTUNITY DETAILS':'申请详情','Add an opportunity':'添加申请','Close':'关闭','Role title':'岗位名称','Institution':'机构','Role type':'岗位类别','Deadline · date only':'截止日期','Official source URL':'官方岗位链接','I personally checked the source; the app has not verified it.':'我已自行核对官方信息。','Materials · one checklist item per line':'所需材料（每行一项）','Private planning notes':'我的笔记','No email or submission will be sent.':'这里仅记录进度。','Save opportunity':'保存申请','saved':'已收藏','preparing':'准备中','submitted':'已提交','interview':'面试中','offer':'已录取','closed':'已结束','missing':'待准备','draft':'草稿','ready':'已完成','Checklist & notes':'材料与笔记','Edit':'编辑','Open source ↗':'查看官方岗位 ↗','Source checked by you':'已自行核对','Source not marked checked':'待核对','No deadline recorded':'截止日期待补充','No opportunities match these filters.':'没有找到符合条件的申请。','Change the search or stage to see your other records.':'换一个关键词或进度试试。','A little structure for a big next step.':'把心动的机会留在这里。','Add your first opportunity, or try clearly fictional examples.':'从发现岗位收藏，或添加自己的第一个申请。','Edit opportunity':'编辑申请','Materials checklist':'材料清单','Planning notes':'我的笔记','No notes yet.':'暂时没有笔记。','Local activity history':'操作记录','Saved in this browser profile.':'已保存在当前浏览器。','← Discover':'← 发现岗位'};
Object.assign(translations,{'Your saved roles and notes stay in this browser. Export a backup to keep a copy.':'岗位和笔记保存在当前浏览器。可导出备份，留存一份。','NextPosition · A next chapter for curious minds.':'下一站 · 为好奇心寻找新的可能。','Manually recorded stage':'申请进度','Your workspace starts empty.':'从第一个感兴趣的岗位开始。','◫ \u00a0 Opportunities':'◫ 全部申请','◷ \u00a0 Due in 14 days':'◷ 两周内截止'});
let lang='zh';try{lang=localStorage.getItem('nextposition-language')||'zh';}catch{}
const originals=new WeakMap();let observer;
function draw(){observer?.disconnect();const walk=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);let n;while((n=walk.nextNode())){if(['SCRIPT','STYLE'].includes(n.parentElement?.tagName))continue;let o=originals.get(n);if(!o||n.nodeValue!==o.last)o={text:n.nodeValue};let v=o.text;if(lang==='zh'){const trim=v.trim();if(translations[trim])v=v.replace(trim,translations[trim]);else if(/^\d+ shown · \d+ total/.test(trim))v=trim.replace(/(\d+) shown · (\d+) total.*/,'显示 $1 项，共 $2 项');else if(/^\d+ \/ \d+ materials ready$/.test(trim))v=trim.replace('materials ready','项材料已完成');}n.nodeValue=v;o.last=v;originals.set(n,o);}document.documentElement.lang=lang==='en'?'en':'zh-CN';observer?.observe(document.body,{subtree:true,childList:true,characterData:true});}
const switcher=document.createElement('button');switcher.textContent=lang==='zh'?'English':'中文';switcher.onclick=()=>{lang=lang==='zh'?'en':'zh';try{localStorage.setItem('nextposition-language',lang);}catch{}switcher.textContent=lang==='zh'?'English':'中文';draw();};document.querySelector('.side-bottom').prepend(switcher);observer=new MutationObserver(draw);draw();
